  ('f57e0ea3-fd7d-4512-bd83-a4c2e3ff54b6', '85bc06aa-304d-42ee-acdf-9d2a74455d68', $$Guerrilla Games ontwikkelt games voor de PlayStation; verkoop via PlayStation Store, gamewinkels en webshops$$,
   $$bedrijfseconomie-vwo-2022-ii-guerrilla-games-context1.png$$,
   $$Guerrilla Games is een van de grootste ontwikkelaars van games. Deze games zijn alleen te spelen op de spelcomputer PlayStation. Via de PlayStation Store (van Google) kunnen de games gedownload worden. Guerrilla Games betaalt hiervoor een commissie van 30% aan Google. Daarnaast zijn de games te koop in fysieke gamewinkels (zoals Game Mania) en online webshops.$$, 'inline'),
  ('a15fc4d6-672e-43e4-abb2-094a17b06c5a', '85bc06aa-304d-42ee-acdf-9d2a74455d68', $$het winstpotentieel van de gamesmarkt in het vijfkrachtenmodel van Porter$$,
   $$bedrijfseconomie-vwo-2022-ii-guerrilla-games-context2.png$$,
   $$Het winstpotentieel van de markt van games voor de PlayStation is met onderstaand vijfkrachtenmodel van Porter weergegeven:$$, 'inline'),
  ('451f2bb3-85a3-4933-8ed4-961011c858b5', '85bc06aa-304d-42ee-acdf-9d2a74455d68', $$vijfkrachtenmodel van Porter: substituten hoog, leveranciers laag, concurrentie hoog, afnemers hoog, nieuwe toetreders laag$$,
   $$bedrijfseconomie-vwo-2022-ii-guerrilla-games-context3.png$$,
   $$Vijfkrachtenmodel van Porter (vijf kaders):
verkrijgbaarheid substituten: hoog
macht van leveranciers: laag
huidige concurrentie: hoog
macht van afnemers: hoog
dreiging nieuwe toetreders: laag$$, 'inline'),
  ('b1dccf12-3399-4d79-a858-dc1ff0d74867', '85bc06aa-304d-42ee-acdf-9d2a74455d68', $$dreiging nieuwe toetreders is laag$$,
   $$bedrijfseconomie-vwo-2022-ii-guerrilla-games-context4.png$$,
   $$In het model van Porter wordt ‘dreiging nieuwe toetreders’ als ‘laag’ beoordeeld.$$, 'inline'),
  ('8e88b5d6-98e3-4172-98ed-856f56f55e7b', '85bc06aa-304d-42ee-acdf-9d2a74455d68', $$SWOT-analyse op basis van het model van Porter$$,
   $$bedrijfseconomie-vwo-2022-ii-guerrilla-games-context5.png$$,
   $$Een marketingmedewerker van Guerrilla Games maakt een SWOT- analyse van Guerrilla Games op basis van bovenstaand model van Porter. De SWOT-analyse maakt onderscheid tussen Strengths, Weaknesses, Opportunities en Threats. Het vijfkrachtenmodel van Porter heeft betrekking op slechts twee van de vier onderdelen van de SWOT-analyse.$$, 'inline'),
  ('76758eda-a6d8-4d1e-a20e-b7074756924e', '85bc06aa-304d-42ee-acdf-9d2a74455d68', $$keuze tussen prijspenetratiepolitiek en afroomprijspolitiek$$,
   $$bedrijfseconomie-vwo-2022-ii-guerrilla-games-context6.png$$,
   $$Bij de prijsstelling van een nieuwe game kan Guerrilla Games kiezen voor een prijspenetratiepolitiek of een afroomprijspolitiek.$$, 'inline'),
  ('02b08956-41fe-47cb-87f3-9f0222a92cba', '85bc06aa-304d-42ee-acdf-9d2a74455d68', $$push- en pull-strategie bij een nieuwe game in 2022$$,
   $$bedrijfseconomie-vwo-2022-ii-guerrilla-games-context7.png$$,
   $$In 2022 zal Guerrilla Games een nieuwe game uitbrengen. Guerrilla Games gaat bij de introductie en verkoop van deze nieuwe game zowel een push–strategie als een pull–strategie hanteren.$$, 'inline'),
  ('f0cfd764-ee4a-4f27-944b-7df2507e8f19', 'ffb91825-1f07-469c-b8bf-89ffce50fcb2', $$inleiding: btw 21%; Massagesalon Knoopweg verkoopt ook massageproducten$$,
